function compileSchema(toolName: string, inputSchema: Record<string, unknown>): ValidateFunction {
  if (!isSchemaObject(inputSchema)) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": invalid schema metadata`);
  }
  try {
    return ajv.compile(inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`);
  }
}

function isSchemaObject(schema: Record<string, unknown>): schema is SchemaObject {
  const {id, $id, $schema, $async} = schema;
  if (id !== undefined && typeof id !== 'string') return false;
  if ($id !== undefined && typeof $id !== 'string') return false;
  if ($schema !== undefined && typeof $schema !== 'string') return false;
  return $async === undefined || $async === false;
}

